import {componentIdentity} from './components.js';
const limit=s=>{if(typeof s!=='string'||s.length>1024*1024)throw Error('Structured comparisons accept text up to 1 MiB per file.');};
// JSON parser retains duplicate-key rejection instead of silently discarding evidence.
export function strictJSON(text){limit(text);let i=0,nodes=0;const ws=()=>{while(/\s/.test(text[i]||'')&&i<text.length)i++;};function value(depth=0){ws();if(depth>32||++nodes>10000)throw Error('JSON structure exceeds comparison bounds.');const c=text[i];if(c==='"'){const m=text.slice(i).match(/^"(?:[^"\\\u0000-\u001f]|\\(?:["\\/bfnrt]|u[0-9a-fA-F]{4}))*"/);if(!m)throw Error('Invalid JSON string.');i+=m[0].length;return JSON.parse(m[0]);}if(c==='{'||c==='['){i++;const object=c==='{',out=object?Object.create(null):[],keys=new Set();ws();if(text[i]===(object?'}':']')){i++;return out;}while(true){let k;if(object){ws();if(text[i]!=='"')throw Error('Expected JSON key.');k=value(depth+1);if(keys.has(k))throw Error('Duplicate JSON key: '+k);keys.add(k);ws();if(text[i++]!==':')throw Error('Expected colon.');}const v=value(depth+1);if(object)out[k]=v;else out.push(v);ws();const end=text[i++];if(end===(object?'}':']'))break;if(end!==',')throw Error('Invalid JSON delimiter.');}return out;}const m=text.slice(i).match(/^(?:true|false|null|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)/);if(!m)throw Error('Invalid JSON value.');i+=m[0].length;const parsed=JSON.parse(m[0]);if(typeof parsed==='number'&&(!Number.isFinite(parsed)||Number.isInteger(parsed)&&!Number.isSafeInteger(parsed)||m[0].split(/[eE]/)[0].replace(/[^0-9]/g,'').replace(/^0+/,'').length>15||parsed===0&&/[1-9]/.test(m[0].split(/[eE]/)[0])))throw Error('Numeric precision exceeds comparison support; retain the original and review it directly.');return parsed;}const out=value();ws();if(i!==text.length)throw Error('Trailing JSON data.');return out;}
export function configMap(text,format){limit(text);const out=new Map();if(format==='JSON'){const walk=(v,path,depth)=>{if(out.size>=5000||depth>32)throw Error('Configuration exceeds comparison bounds.');if(v&&typeof v==='object'&&Object.keys(v).length){out.set(JSON.stringify(['type',path]),Array.isArray(v)?'array':'object');for(const k of Object.keys(v))walk(v[k],path+'/'+k.replaceAll('~','~0').replaceAll('/','~1'),depth+1);}else out.set(JSON.stringify(['value',path]),JSON.stringify(v));};walk(strictJSON(text),'',0);}else if(format==='ENV'){for(const raw of text.split(/\r?\n/)){const line=raw.trim();if(!line||line.startsWith('#'))continue;const m=line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);if(!m)throw Error('Unsupported literal .env line.');let v=m[2].trim();if(/[`$]/.test(v))throw Error('Shell substitution and interpolation are not interpreted.');if(v.startsWith("'")||v.startsWith('"')){const q=v[0],end=v.indexOf(q,1);if(end<0||v.slice(end+1).trim()&&!v.slice(end+1).trim().startsWith('#')||v.slice(1,end).includes('\\'))throw Error('Unsupported quoted .env value.');v=v.slice(1,end);}else{v=v.replace(/\s+#.*$/,'').trim();if(/[\s\\;|&<>]/.test(v))throw Error('Unsupported .env syntax.');}if(out.has(m[1]))throw Error('Duplicate configuration key: '+m[1]);out.set(m[1],v);if(out.size>5000)throw Error('Too many configuration entries.');}}else if(format==='INI'){let section='';for(const raw of text.split(/\r?\n/)){const line=raw.trim();if(!line||/^[;#]/.test(line))continue;const m=line.match(/^\[([^\]]+)\]$/);if(m){section=m[1];continue;}const a=line.match(/^([^=]+?)\s*=\s*(.*)$/);if(!a)throw Error('Unsupported INI/key=value line; continuation and shell syntax are not interpreted.');const key=JSON.stringify([section,a[1].trim()]);if(out.has(key))throw Error('Duplicate configuration key: '+key);out.set(key,a[2]);if(out.size>5000)throw Error('Too many configuration entries.');}}else throw Error('Choose JSON, INI or ENV.');return out;}
const sensitive=k=>/password|passwd|secret|token|credential|private.?key|api.?key/i.test(k);
export function compareConfigs(a,b,format){const x=configMap(a,format),y=configMap(b,format),rows=[];for(const key of new Set([...x.keys(),...y.keys()]))if(x.get(key)!==y.get(key)||x.has(key)!==y.has(key))rows.push({key:format==='JSON'?(JSON.parse(key)[1]||'/')+(JSON.parse(key)[0]==='type'?' (container type)':''):key,change:!x.has(key)?'Added':!y.has(key)?'Removed':'Changed',before:!x.has(key)?'(absent)':sensitive(key)?'[masked]':x.get(key).slice(0,500),after:!y.has(key)?'(absent)':sensitive(key)?'[masked]':y.get(key).slice(0,500)});return {format,rows,limitation:'Parsed key/value changes only. Comments and formatting are ignored; configuration behavior and remediation require review.'};}
export function compareComponents(a,b){const key=x=>componentIdentity(x).key;const x=new Map(),y=new Map();for(const [list,map] of [[a,x],[b,y]]){if(list.length>10000)throw Error('Too many SBOM components.');for(const c of list){const k=key(c);map.set(k,[...(map.get(k)||[]),c]);}}const rows=[];for(const k of new Set([...x.keys(),...y.keys()])){const A=x.get(k)||[],B=y.get(k)||[];if(A.length>1||B.length>1){rows.push({key:k,change:'Ambiguous component identity',before:A.length+' candidates',after:B.length+' candidates'});continue;}const before=A[0],after=B[0];if(!before||!after||before.version!==after.version||before.license!==after.license)rows.push({key:k,change:!before?'Added':!after?'Removed':'Version / license changed',before:before?before.version+' · '+before.license:'(absent)',after:after?after.version+' · '+after.license:'(absent)'});}return {rows,limitation:'SBOM declarations are not proof of installed or reachable components. Missing or invalid PURLs use declared ecosystem, supplier, group and name; duplicates remain ambiguous. No CVE applicability is inferred.'};}
